def main():
    OUT.parent.mkdir(parents=True, exist_ok=True)
    now = datetime.now(TEHRAN)
    index = int(now.strftime("%Y%j")) % len(TOPICS)
    category, title, body, question = TOPICS[index]
    post = (f"📚 فاندبورد نقره | {category}\n\n{title}\n\n{body}\n\n💬 {question}"
            "\n\n@FundBoard_Silver | فاندبورد نقره\n‎داشبورد سرمایه‌گذاری شما")
    OUT.write_text(post, encoding="utf-8")
    digest = hashlib.sha256(post.encode()).hexdigest()[:12]
    print(json.dumps({"mode":"DRY_RUN","date":now.isoformat(),"topic_index":index,
                      "topic_count":len(TOPICS),"sha256_prefix":digest,"preview":post,
                      "telegram_messages_sent":0},ensure_ascii=False,indent=2))


if __name__ == "__main__":
    main()
